"""Cached media derivatives generated by the single worker."""
from dataclasses import asdict
import json
import os
from pathlib import Path
from tempfile import TemporaryDirectory
import time

from fastapi import HTTPException

from app.config import Settings
from app.services.audio import Media, extract, input_format, probe
from app.utils.files import child, source_path, write_json
from app.utils.process import run
from app.v2.analysis import FaceTracks, audio_features, event
from app.v2.assets import asset_record
from app.v2.presets import processing_settings


def cache_folder(settings, row, *, preset=None):
    settings = processing_settings(settings, preset or json.loads(row["metadata"]).get("processing_preset"))
    fingerprint = row["digest"] or ("legacy-" + row["id"])
    source = source_path(settings.root/"input", row["stored_name"], settings.max_input_bytes)
    if row["digest"] is None:
        stat = source.stat()
        fingerprint += f"-{stat.st_size}-{stat.st_mtime_ns}"
    parent = child(settings.root / "storage", "media-cache")
    return child(parent, f"{fingerprint}-v1-{settings.visual_sample_seconds:g}-{settings.visual_max_samples}")


def browser_compatible(path, metadata):
    return (path.suffix.lower() == ".mp4" and metadata.get("video_codec") == "h264"
            and metadata.get("pixel_format") in {"yuv420p","yuvj420p"}
            and all(codec == "aac" for codec in metadata.get("audio_codecs", ())))


def preview_path(settings, row):
    source = source_path(settings.root/"input", row["stored_name"], settings.max_input_bytes)
    metadata = json.loads(row["metadata"])
    if browser_compatible(source, metadata) or (not metadata and source.suffix.lower() == ".mp4"):
        return source
    path = child(cache_folder(settings, row), "proxy.mp4")
    if not path.is_file():
        raise HTTPException(409, "The browser proxy is not ready. Check asset preparation.")
    return path


def read_manifest(settings, row, *, preset=None):
    path = child(cache_folder(settings, row, preset=preset), "analysis.json")
    if not path.is_file():
        raise HTTPException(409, "Source analysis is not ready. Check asset preparation.")
    return json.loads(path.read_text(encoding="utf-8"))


def thumbnail_path(settings, row, index=0):
    manifest = read_manifest(settings, row)
    if not 0 <= index < len(manifest["thumbnail_times"]):
        raise HTTPException(404, "Source thumbnail not found")
    return child(cache_folder(settings,row), f"thumb-{index:03}.jpg")


def timeline(settings, row):
    from app.v2.tracking import recommendation

    manifest = read_manifest(settings, row)
    facts = json.loads(row["metadata"])
    layout = recommendation(manifest["tracks"], manifest["sample_count"], row["content_type"],
                            facts["width"], facts["height"], manifest["duration"])
    return {"duration": manifest["duration"], "waveform": manifest["waveform"],
            "thumbnails": [{"time": at, "url": f"/api/v2/assets/{row['id']}/thumbnail?index={index}"}
                           for index, at in enumerate(manifest["thumbnail_times"])],
            "tracks": manifest["tracks"], "events": manifest["events"],
            "sample_interval": manifest["sample_interval"], "audio_available": manifest["audio_available"],
            "recommendation": layout}


def _frame_analysis(settings, media, source, folder, cancel):
    import cv2
    import numpy as np
    from scenedetect.detectors import ContentDetector

    # The sampling rate scales with source length. Image filenames are actual frame PTS in milliseconds.
    step = max(settings.visual_sample_seconds, media.duration / settings.visual_max_samples)
    cascade = cv2.CascadeClassifier(str(Path(cv2.data.haarcascades)/"haarcascade_frontalface_default.xml"))
    if cascade.empty():
        raise RuntimeError("The OpenCV face detector is unavailable")
    args = [settings.executable("ffmpeg"), "-v", "error", "-nostdin", "-n", "-protocol_whitelist", "file",
            "-f", input_format(source), "-threads", str(settings.cpu_threads), "-i", str(source),
            "-map", f"0:{media.video_stream}", "-an", "-filter_threads", str(settings.cpu_threads),
            "-vf", f"select='isnan(prev_selected_t)+gte(t-prev_selected_t,{step:.6f})',"
                   "scale=640:640:force_original_aspect_ratio=decrease:force_divisible_by=2",
            "-fps_mode", "passthrough", "-enc_time_base", "1:1000", "-frame_pts", "1", "-q:v","4",
            "-threads:v","1","-frames:v",str(settings.visual_max_samples), str(folder/"sample-%012d.jpg")]
    run(args, cwd=folder, timeout=settings.ffmpeg_timeout, check_cancel=cancel)
    frames = sorted(folder.glob("sample-*.jpg"))
    if not frames:
        raise ValueError("No video frames could be decoded for this asset")
    keep = set(np.linspace(0, len(frames)-1, min(12, len(frames)), dtype=int))
    last = None
    times, thumbs, events = [], [], []
    tracks = FaceTracks(step)
    detector = ContentDetector(min_scene_len=1)
    for i, path in enumerate(frames):
        cancel()
        at = max(0., min(media.duration, int(path.stem.removeprefix("sample-")) / 1000))
        times.append(at)
        frame = cv2.imdecode(np.frombuffer(path.read_bytes(), dtype=np.uint8), cv2.IMREAD_COLOR)
        if frame is None:
            raise ValueError("A sampled video frame could not be decoded")
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        height, width = gray.shape
        faces = cascade.detectMultiScale(cv2.equalizeHist(gray), scaleFactor=1.1, minNeighbors=5, minSize=(18,18))
        boxes = [{"x":round(x/width,6), "y":round(y/height,6), "width":round(w/width,6), "height":round(h/height,6)}
                 for x,y,w,h in faces]
        tracks.update(at, boxes)
        for cut in detector.process_frame(i, frame):
            if cut > 0:
                events.append(event(times[cut-1], times[cut], "scene_change", .85,
                                    "ContentDetector flagged a change between these sampled frames.",
                                    min(.85, 1 / max(1., step / 2))))
        if last is not None:
            difference = float(cv2.mean(cv2.absdiff(last, gray))[0] / 255.)
            if difference >= .045:
                events.append(event(times[i-1], at, "motion", difference/.35,
                                    f"Mean absolute luma change was {difference:.3f} between sampled frames.",
                                    min(.85, 1 / max(1., step / 2))))
        last = gray
        if i in keep:
            path.rename(folder / f"thumb-{len(thumbs):03}.jpg")
            thumbs.append(at)
        else:
            path.unlink()
    return thumbs, tracks.tracks, events, step, len(frames)


def prepare_asset(settings: Settings, db, asset_id, cancel=lambda: None, *, preset=None):
    row = asset_record(db,asset_id)
    folder = cache_folder(settings,row,preset=preset)
    if (folder / "analysis.json").is_file():
        return read_manifest(settings,row,preset=preset)
    source = source_path(settings.root / "input",row["stored_name"],settings.max_input_bytes)
    facts = json.loads(row["metadata"])
    preferred = facts.pop("processing_preset", None)
    settings = processing_settings(settings, preset or preferred)
    media = Media(**{key: facts[key] for key in Media.__dataclass_fields__}) if facts else probe(settings, source, cancel)
    if not facts:
        with db.transaction(write=True) as c:
            c.execute("UPDATE assets SET metadata=? WHERE id=?", (json.dumps(asdict(media)), asset_id))
    folder.parent.mkdir(parents=True, exist_ok=True)
    with TemporaryDirectory(prefix="prepare-", dir=folder.parent) as tmp:
        staging = Path(tmp)
        start = time.monotonic()
        audio_started = start
        waveform, events, rms = [], [], []
        if media.audio_streams:
            wav = staging / "analysis.wav"
            extract(settings, source, media.audio_streams[0], wav, cancel)
            waveform, events, rms = audio_features(wav, media.duration, cancel)
            wav.unlink()
        audio_seconds = time.monotonic() - audio_started
        visual_started = time.monotonic()
        thumbs, tracks, visual_events, step, samples = _frame_analysis(settings,media,source,staging,cancel)
        visual_seconds = time.monotonic() - visual_started
        if not browser_compatible(source, asdict(media)):
            args = [settings.executable("ffmpeg"), "-v", "error", "-nostdin", "-n", "-protocol_whitelist", "file",
                    "-f",input_format(source), "-threads",str(settings.cpu_threads), "-i",str(source),
                    "-map",f"0:{media.video_stream}", "-filter_threads",str(settings.cpu_threads)]
            if media.audio_streams:
                args += ["-map",f"0:{media.audio_streams[0]}","-c:a","aac","-b:a","96k"]
            args += ["-vf","scale=960:540:force_original_aspect_ratio=decrease:force_divisible_by=2",
                     "-map_metadata","-1","-map_chapters","-1","-c:v","libx264","-threads",str(settings.cpu_threads),
                     "-pix_fmt","yuv420p","-preset","veryfast","-crf","27","-movflags","+faststart",str(staging/"proxy.mp4")]
            run(args, cwd=staging, timeout=settings.ffmpeg_timeout, check_cancel=cancel)
            proxy = probe(settings, staging/"proxy.mp4",cancel)
            if proxy.video_codec != "h264" or abs(proxy.duration-media.duration)>max(.5,1/max(1.,media.fps)):
                raise ValueError("The generated proxy failed the codec or duration check")
        manifest = {"duration":media.duration, "waveform":waveform, "audio_measurements":rms,
                    "audio_available":bool(rms),"sample_interval":step, "sample_count":samples,
                    "thumbnail_times":thumbs, "tracks":tracks,
                    "events":[item.model_dump() for item in sorted(events+visual_events,key=lambda e:e.start)],
                    "stage_seconds":{"audio_analysis":round(audio_seconds,3), "visual_analysis":round(visual_seconds,3)},
                    "elapsed_seconds":round(time.monotonic()-start,3)}
        write_json(staging/"analysis.json",manifest)
        cancel()
        # The directory is made visible only after the preview and every sidecar has been closed.
        if folder.exists():
            raise RuntimeError("An incomplete or unexpected media cache already occupies the asset folder")
        os.rename(staging,folder)
    return manifest
